package retentioncompleteness

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"path/filepath"
	"reflect"
	"strings"

	"github.com/MarcosAlves90/polis/v6/internal/artifactretention"
	"github.com/MarcosAlves90/polis/v6/internal/gitutil"
	"github.com/MarcosAlves90/polis/v6/spec"
)

const (
	classContracts = "contracts"
	classPlans     = "plans"
	classProofs    = "proofs"
	classEvidence  = "evidence"

	maxCompletionRead = 16 << 20
)

// Publisher publishes exact generated bytes through the repository's retention
// state. The default uses the managed artifact API directly; callers may wrap
// it to observe failures without changing the published bytes.
type Publisher func(context.Context, artifactretention.State, string, []artifactretention.Artifact) ([]string, error)

// Inputs describes one completed locked-change validation run.
type Inputs struct {
	Operation             string
	ContractRaw           []byte
	Contract              spec.ChangeContract
	PolicyRaw             []byte
	Policy                spec.Policy
	ImplementationPlanRaw []byte
	RegressionPatch       []byte
	Evidence              []byte
	BaseCommit            string
	TargetTree            string
	ValidationLevel       string
	EnabledGates          []string
	DisabledGates         []string
	DeferredGates         []string
	ProducerGateStatuses  map[string]spec.Status
}

// Outcome reports the published artifacts, the bounded completion record, and
// the post-publication verification that gates a successful command result.
type Outcome struct {
	Record           spec.RetainedValidationRecord
	RecordPath       string
	PublicationPaths []string
	Verification     Verification
}

type publishItem struct {
	class string
	data  []byte
}

func DefaultPublisher(_ context.Context, state artifactretention.State, repo string, artifacts []artifactretention.Artifact) ([]string, error) {
	return state.PublishMany(repo, artifacts)
}

// Complete publishes the stage-required artifacts, publishes a bounded
// completion record, and verifies every published artifact through safe readers
// before returning.
func Complete(ctx context.Context, state artifactretention.State, repo string, inputs Inputs, publisher Publisher) (Outcome, error) {
	if publisher == nil {
		publisher = DefaultPublisher
	}
	normalized, err := normalizeInputs(inputs)
	if err != nil {
		return Outcome{}, err
	}
	items, err := requiredArtifacts(normalized)
	if err != nil {
		return Outcome{}, err
	}
	artifacts := make([]artifactretention.Artifact, 0, len(items))
	for _, item := range items {
		artifacts = append(artifacts, artifactretention.Artifact{Class: item.class, Data: item.data})
	}
	paths, err := publisher(ctx, state, repo, artifacts)
	if err != nil {
		return Outcome{}, fmt.Errorf("publish retained validation artifacts: %w", err)
	}
	if len(paths) != len(items) {
		return Outcome{}, fmt.Errorf("publisher returned %d paths for %d retained validation artifacts", len(paths), len(items))
	}
	classPaths, err := checkedPublicationPaths(items, paths)
	if err != nil {
		return Outcome{}, err
	}
	record, err := newRecord(normalized, classPaths)
	if err != nil {
		return Outcome{}, err
	}
	recordRaw, err := spec.EncodeRetainedValidationRecord(record)
	if err != nil {
		return Outcome{}, err
	}
	recordPaths, err := publisher(ctx, state, repo, []artifactretention.Artifact{{Class: classEvidence, Data: recordRaw}})
	if err != nil {
		return Outcome{}, fmt.Errorf("publish retained validation record: %w", err)
	}
	if len(recordPaths) != 1 || recordPaths[0] != expectedPath(classEvidence, digestHex(recordRaw)) {
		return Outcome{}, errors.New("publisher returned an unexpected retained validation record path")
	}
	verification, err := Verify(ctx, VerifyOptions{
		Retention:      state,
		Repo:           repo,
		RecordPath:     recordPaths[0],
		ExpectedRecord: &record,
		ContractRaw:    normalized.ContractRaw,
		Contract:       normalized.Contract,
		PolicyRaw:      normalized.PolicyRaw,
		Policy:         normalized.Policy,
		EvidenceRaw:    normalized.Evidence,
		PlanRaw:        normalized.ImplementationPlanRaw,
		ProofRaw:       normalized.RegressionPatch,
		TargetTree:     normalized.TargetTree,
	})
	if err != nil {
		return Outcome{}, fmt.Errorf("verify retained validation completion: %w", err)
	}
	return Outcome{
		Record: record, RecordPath: recordPaths[0], PublicationPaths: append([]string(nil), paths...), Verification: verification,
	}, nil
}

func normalizeInputs(inputs Inputs) (Inputs, error) {
	locked := len(inputs.ContractRaw) > 0 && inputs.Contract.BaselineLock != nil
	decodedContract := spec.ChangeContract{}
	decodeErr := error(nil)
	if locked {
		decodedContract, decodeErr = spec.DecodeChangeContract(inputs.ContractRaw)
	}
	baseMatches := locked && inputs.BaseCommit == inputs.Contract.BaselineLock.BaseCommit
	policyMatches := locked && digestHex(inputs.PolicyRaw) == inputs.Contract.BaselineLock.PolicySHA256
	requiresProof := locked && inputs.Contract.RequiresRedGreen()
	for _, check := range []struct {
		ok  bool
		err error
	}{
		{inputs.Operation == spec.RetainedValidationOperationWorkspace || inputs.Operation == spec.RetainedValidationOperationBuild, fmt.Errorf("unsupported retention completion operation %q", inputs.Operation)},
		{locked, errors.New("retained validation completion requires a locked Change Contract")},
		{len(inputs.PolicyRaw) > 0, errors.New("retained validation completion requires the exact policy bytes")},
		{len(inputs.Evidence) > 0, errors.New("retained validation completion requires validation evidence")},
		{inputs.TargetTree != "", errors.New("retained validation completion requires a target tree")},
		{locked && inputs.Contract.IsLockedStrictDevelopment() && inputs.Contract.DevelopmentMethod == spec.DevelopmentMethodStrictSDDTDDV2, errors.New("retained validation completion requires a locked strict_sdd_tdd_v2 Change Contract")},
		{decodeErr == nil, fmt.Errorf("decode retained validation contract: %w", decodeErr)},
		{inputs.ProducerGateStatuses != nil, errors.New("retained validation completion requires producer gate outcomes")},
		{baseMatches, errors.New("retained validation completion base commit differs from the locked contract")},
		{policyMatches, errors.New("retained validation completion policy differs from the locked baseline policy")},
		{!requiresProof || len(inputs.RegressionPatch) > 0, errors.New("Red-to-Green retained validation completion requires a captured Red proof")},
		{requiresProof || len(inputs.RegressionPatch) == 0, errors.New("Green-to-Green retained validation completion must not retain a Red proof")},
	} {
		if !check.ok {
			return Inputs{}, check.err
		}
	}
	if locked && !reflect.DeepEqual(decodedContract, inputs.Contract) {
		return Inputs{}, errors.New("contract struct differs from the exact retained Change Contract bytes")
	}
	boundPolicy, policyErr := decodeBoundPolicy(inputs.PolicyRaw, inputs.Policy)
	if policyErr != nil {
		return Inputs{}, policyErr
	}
	inputs.Contract = decodedContract
	inputs.Policy = boundPolicy
	if inputs.ValidationLevel == "" {
		inputs.ValidationLevel = inputs.Policy.ValidationSummary().Level
	}
	summary := inputs.Policy.ValidationSummary()
	inputs.EnabledGates = cloneStrings(inputs.EnabledGates, summary.EnabledGates)
	inputs.DisabledGates = cloneStrings(inputs.DisabledGates, summary.DisabledGates)
	inputs.DeferredGates = cloneStrings(inputs.DeferredGates, nil)
	return inputs, nil
}

func checkedPublicationPaths(items []publishItem, paths []string) (map[string]string, error) {
	classPaths := make(map[string]string, len(items))
	for index, item := range items {
		if paths[index] != expectedPath(item.class, digestHex(item.data)) {
			return nil, fmt.Errorf("publisher returned unexpected retained %s path %q", item.class, paths[index])
		}
		classPaths[item.class] = paths[index]
	}
	return classPaths, nil
}

func requiredArtifacts(inputs Inputs) ([]publishItem, error) {
	items := []publishItem{
		{class: classContracts, data: inputs.ContractRaw},
		{class: classEvidence, data: inputs.Evidence},
	}
	if len(inputs.ImplementationPlanRaw) > 0 {
		items = append(items, publishItem{class: classPlans, data: inputs.ImplementationPlanRaw})
	}
	if len(inputs.RegressionPatch) > 0 {
		items = append(items, publishItem{class: classProofs, data: inputs.RegressionPatch})
	}
	return items, nil
}

func cloneStrings(values, fallback []string) []string {
	source := values
	if len(source) == 0 {
		source = fallback
	}
	result := make([]string, len(source))
	copy(result, source)
	return result
}

func newRecord(inputs Inputs, paths map[string]string) (spec.RetainedValidationRecord, error) {
	lock := inputs.Contract.BaselineLock
	record := spec.RetainedValidationRecord{
		SchemaVersion:            spec.RetainedValidationRecordSchemaVersion,
		Kind:                     spec.RetainedValidationKind,
		Operation:                inputs.Operation,
		Status:                   spec.RetainedValidationStatusPASS,
		GitObjectFormat:          lock.GitObjectFormat,
		BaseCommit:               lock.BaseCommit,
		BaseTree:                 lock.BaseTree,
		PolicySHA256:             digestHex(inputs.PolicyRaw),
		SpecificationSHA256:      lock.SpecificationSHA256,
		TargetTree:               inputs.TargetTree,
		ContractSHA256:           digestHex(inputs.ContractRaw),
		ImplementationPlanSHA256: optionalDigest(inputs.ImplementationPlanRaw),
		RegressionPatchSHA256:    optionalDigest(inputs.RegressionPatch),
		EvidenceSHA256:           digestHex(inputs.Evidence),
		ValidationLevel:          inputs.ValidationLevel,
		EnabledGates:             cloneStrings(inputs.EnabledGates, nil),
		DisabledGates:            cloneStrings(inputs.DisabledGates, nil),
		DeferredGates:            cloneStrings(inputs.DeferredGates, nil),
		ProducerGateStatuses:     cloneStatuses(inputs.ProducerGateStatuses),
		RetainedContract:         paths[classContracts],
		RetainedPlan:             paths[classPlans],
		RetainedProof:            paths[classProofs],
		RetainedEvidence:         paths[classEvidence],
	}
	if err := spec.ValidateRetainedValidationRecord(record); err != nil {
		return spec.RetainedValidationRecord{}, err
	}
	return record, nil
}

func decodeBoundPolicy(raw []byte, policy spec.Policy) (spec.Policy, error) {
	decoded, err := spec.DecodePolicy(raw)
	if err != nil {
		return spec.Policy{}, fmt.Errorf("decode validated Project Policy: %w", err)
	}
	if !reflect.DeepEqual(decoded, policy) {
		return spec.Policy{}, errors.New("policy struct differs from the exact validated Project Policy bytes")
	}
	return decoded, nil
}

func cloneStatuses(statuses map[string]spec.Status) map[string]spec.Status {
	result := make(map[string]spec.Status, len(statuses))
	for gate, status := range statuses {
		result[gate] = status
	}
	return result
}

func optionalDigest(data []byte) string {
	if len(data) == 0 {
		return ""
	}
	return digestHex(data)
}

func digestHex(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func expectedPath(class, digest string) string {
	extension := ".json"
	if class == classProofs {
		extension = ".patch"
	}
	return ".polis/artifacts/" + class + "/sha256-" + digest + extension
}

// TargetTree computes the current source tree with a temporary index, excluding
// the managed artifact root. It never mutates the repository's real index.
func TargetTree(ctx context.Context, repo, baseCommit string) (string, error) {
	root, err := filepath.Abs(repo)
	if err != nil {
		return "", err
	}
	staged, err := artifactretention.StagedChanges(ctx, root)
	if err != nil {
		return "", err
	}
	if staged {
		return "", errors.New("source index contains staged changes; repository retention readiness is unavailable")
	}
	indexPath, cleanupIndex, err := gitutil.TemporaryIndex("polis-retention-index-*")
	if err != nil {
		return "", fmt.Errorf("allocate temporary index: %w", err)
	}
	defer cleanupIndex()
	objectEnv, cleanupObjects, err := gitutil.TemporaryObjectEnv(ctx, root, "polis-retention-objects-*")
	if err != nil {
		return "", fmt.Errorf("allocate temporary object directory: %w", err)
	}
	defer cleanupObjects()
	env := append(objectEnv, "GIT_INDEX_FILE="+indexPath)
	if _, err := gitutil.Bytes(ctx, root, env, nil, "read-tree", baseCommit); err != nil {
		return "", fmt.Errorf("initialize temporary index: %w", err)
	}
	if _, err := gitutil.Bytes(ctx, root, env, nil, "add", "-A", "--", ".", ":(exclude).polis/artifacts/**"); err != nil {
		return "", fmt.Errorf("capture source tree: %w", err)
	}
	tree, err := gitutil.Output(ctx, root, env, nil, "write-tree")
	if err != nil {
		return "", fmt.Errorf("write source tree: %w", err)
	}
	return tree, nil
}

func equalStrings(left, right []string) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		if left[index] != right[index] {
			return false
		}
	}
	return true
}

func describePaths(paths []string) string {
	if len(paths) == 0 {
		return "none"
	}
	return strings.Join(paths, ", ")
}

func readRetained(state artifactretention.State, repo, path, class, label string) ([]byte, error) {
	if path == "" {
		return nil, fmt.Errorf("missing retained %s path", label)
	}
	raw, err := state.ReadInput(repo, filepath.Join(repo, filepath.FromSlash(path)), class, maxCompletionRead, label+" exceeds maximum size")
	if err != nil {
		return nil, fmt.Errorf("read retained %s %s: %w", label, path, err)
	}
	return raw, nil
}

func equalBytes(left, right []byte) bool {
	return bytes.Equal(left, right)
}
